package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerWestNineCoveredCooldownStageTest {
 private Crab old,west;
 private Room room(){Room r=new Room();r.wave=9;r.spawns[8]=52;r.spawns[9]=56;r.ready=61;r.player=RangerStrategy.tile(3300,4245);old=new Crab(30,30,52,8,Lane.EAST,'S',false,Style.RANGE,RangerStrategy.tile(3302,4248));old.pendingDamage=6;r.crabs.add(old);west=new Crab(34,34,56,9,Lane.WEST,'S',true,Style.RANGE,RangerStrategy.tile(3285,4248));west.pendingDamage=0;r.crabs.add(west);return r;}
 @Test public void nativeLastCooldownCanMoveWestWithoutAbandoningRealSmallFollowup(){Room r=room();RangerStrategy s=new RangerStrategy();s.attacked(new Decision(old,Weapon.PIPE,r.player,false,null,"actualpriorhit"),59);Decision d=s.decide(r,60);assertNull(d.target);assertNull(d.approach);assertEquals("Stage West9 while covering the next small shot",d.reason);assertEquals(RangerStrategy.tile(3298,4247),d.tile);assertTrue(org.localscape.nylocas.AttackTiming.distance(d.tile,old.point,false)<=4);}
 @Test public void actualSmallFollowupStillFiresAtTheSameReadyTick(){Room r=room();RangerStrategy s=new RangerStrategy();s.attacked(new Decision(old,Weapon.PIPE,r.player,false,null,"actualpriorhit"),59);Decision prep=s.decide(r,60);r.player=prep.tile;old.point=RangerStrategy.tile(3301,4248);old.hp=2;old.pendingDamage=0;Decision d=s.decide(r,61);assertSame(d.reason,old,d.target);assertEquals(Weapon.PIPE,d.weapon);}
 @Test public void noReadyTickIsSpentOnThisPositioning(){Room r=room();r.ready=60;Decision d=new RangerStrategy().decide(r,60);assertSame(old,d.target);assertNotEquals("Stage West9 while covering the next small shot",d.reason);}
 @Test public void earlierCooldownDoesNotAssumeOnlyOneTargetMovement(){Room r=room();r.ready=62;assertNotEquals("Stage West9 while covering the next small shot",new RangerStrategy().decide(r,60).reason);}
 @Test public void tightRayOrUnknownOrLethalCurrentWorkCannotJustifyTheMove(){for(int g=0;g<3;g++){Room r=room();if(g==0)r.obstructed.add(old.key);if(g==1)old.pendingDamage=-1;if(g==2)old.pendingDamage=8;assertNotEquals("Stage West9 while covering the next small shot",new RangerStrategy().decide(r,60).reason);}}
 @Test public void nullOrCoveredOrAlreadyOpenedParentDoesNotPullPosition(){for(int g=0;g<3;g++){Room r=room();RangerStrategy s=new RangerStrategy();if(g==0)west.nulled=true;if(g==1)west.pendingDamage=16;if(g==2)s.attacked(new Decision(west,Weapon.PIPE,r.player,false,null,"actualopening"),58);assertNotEquals("Stage West9 while covering the next small shot",s.decide(r,60).reason);}}
 @Test public void aSmallOutsideTheMarginDoesNotLoseItsShot(){Room r=room();old.point=RangerStrategy.tile(3303,4248);assertNotEquals("Stage West9 while covering the next small shot",new RangerStrategy().decide(r,60).reason);}
 @Test public void theMoveEndsBeforeTheLateNineOrTenPacketWindows(){Room r=room();r.ready=64;assertNotEquals("Stage West9 while covering the next small shot",new RangerStrategy().decide(r,63).reason);r=room();r.wave=10;r.spawns[10]=68;r.ready=69;assertNotEquals("Stage West9 while covering the next small shot",new RangerStrategy().decide(r,68).reason);}
 @Test public void theSameFollowupCanLeavePipeReadyForTheParentInsteadOfBow(){Room r=room();RangerStrategy s=new RangerStrategy();s.attacked(new Decision(old,Weapon.PIPE,r.player,false,null,"actualpriorhit"),59);Decision prep=s.decide(r,60);r.player=prep.tile;old.point=RangerStrategy.tile(3301,4248);old.hp=2;old.pendingDamage=0;Decision follow=s.decide(r,61);s.attacked(follow,61);old.hp=0;old.dying=true;r.ready=63;west.point=RangerStrategy.tile(3287,4248);Decision next=s.decide(r,62);assertTrue(next.reason,next.target==west||next.approach==west);assertEquals(next.reason,Weapon.PIPE,next.weapon);}
}